const express = require('express');
const crypto = require('crypto');
const { CustomerDb, TenantMembership } = require('../models/customer');

const app = express();
app.use(express.json());

app.post('/api/webhooks/auth0/delete-user', async (req, res) => {
  const signature = req.headers['x-auth0-signature'];
  const expectedSig = crypto
    .createHmac('sha256', process.env.AUTH0_DELETE_WEBHOOK_SECRET)
    .update(JSON.stringify(req.body))
    .digest('hex');

  if (!signature || signature !== expectedSig) {
    return res.status(401).json({ error: 'Invalid webhook signature' });
  }

  const { auth0UserId, requestingTenantId } = req.body;

  // Ensure deletion is strictly scoped to the tenant initiating the request
  const isMember = await TenantMembership.exists({
    tenantId: requestingTenantId,
    auth0Id: auth0UserId
  });

  if (!isMember) {
    return res.status(403).json({ error: 'Access denied: user does not belong to requesting tenant' });
  }

  const deletedCount = await CustomerDb.deleteMany({
    externalAuth0Id: auth0UserId,
    tenantId: requestingTenantId
  });

  res.json({ status: 'DELETED', deletedCount, auth0UserId });
});

app.listen(9007);
